add_filter('the_content', function($content) {
    if (is_singular('post') && !is_admin() && !empty($content)) {

        // Split content by H2
        $parts = preg_split('/(<h2[^>]*>)/i', $content, -1, PREG_SPLIT_DELIM_CAPTURE | PREG_SPLIT_NO_EMPTY);
        $new_content = '<div class="post-section-box intro-section">'; 

        foreach ($parts as $part) {
            if (preg_match('/<h2[^>]*>/i', $part)) {
                $new_content .= '</div><div class="post-section-box">' . $part;
            } else {
                $new_content .= $part;
            }
        }
        $new_content .= '</div>';

        // Separate TOC from the boxes
        if (stripos($new_content, '<details class="bk-toc-wrapper"') !== false) {
            $new_content = str_replace('<details class="bk-toc-wrapper"', '</div><details class="bk-toc-wrapper"', $new_content);
            $new_content = str_replace('</details>', '</details><div class="post-section-box">', $new_content);
        }

        // Final cleanup for any empty boxes
        return preg_replace('/<div class="post-section-box[^>]*>\s*<\/div>/', '', $new_content);
    }
    return $content;
}, 30);
